def t(key, lang=None, **fmt):
    """Look up a string, safely falling back to English and tolerating format errors."""
    try:
        chosen_lang = lang or session.get('lang', 'en')
        if chosen_lang not in SUPPORTED_LANGS:
            chosen_lang = 'en'
        translations = TRANSLATIONS.get(key)
        if not translations:
            return str(key)
        text = translations.get(chosen_lang, translations.get('en', str(key)))
        if fmt:
            try:
                text = text.format(**fmt)
            except (KeyError, ValueError, IndexError):
                pass
        return text
    except Exception:
        return str(key)
